11	/**
12	 * Runs first in the create-owner pipeline. Rejects a request that is missing or blank in any of
13	 * firstName, lastName, address, city or telephone with a 400 naming each offending field, before
14	 * {@link BuildOwner} runs. Publishes the validated body for later steps as they must not bind the
15	 * request body a second time.
16	 *
17	 * <p>The address is {@link OwnerAddresses#normalize normalized} in place before it is checked and
18	 * published, so an address that is blank only after normalization is rejected here and every later
19	 * step (build, household comparison, store/return) works with the single normalized form.
20	 */
21	public class ValidateOwnerFields {
22	
23	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
24	            throws MissingOwnerFieldsException {
25	        request.setAddress(OwnerAddresses.normalize(request.getAddress()));
26	
27	        List<String> missing = new ArrayList<>();
28	        require("firstName", request.getFirstName(), missing);
29	        require("lastName", request.getLastName(), missing);
30	        require("address", request.getAddress(), missing);
31	        require("city", request.getCity(), missing);
32	        require("telephone", request.getTelephone(), missing);
33	        if (!missing.isEmpty()) {
34	            throw new MissingOwnerFieldsException(missing);
35	        }
36	        validated.set(request);
37	    }
38	
39	    private static void require(String name, String value, List<String> missing) {
40	        if (value == null || value.isBlank()) {
41	            missing.add(name);
42	        }
43	    }
44	}
